package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a merge by anyone but a steward. */
public class ValidateMerge {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody MergeRequest request, RoleStore roles,
            Out<MergeRequest> body) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        if (roles.find(sheetId.trim(), user) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward may merge people");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

/** Body of a merge: the id of the person merged into, and who merges them. */
public record MergeRequest(Long into, String user) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonStore store, Out<Person> personOut) throws InvalidSheetException {
        Person person = null;
        try {
            person = store.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (person == null) {
            throw new InvalidSheetException("No such person: " + personId);
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Takes the sheet's figures before a change, so its audit step can record how the change moved them. */
public class SnapshotRollup {
    public void snapshot(@PathVariable("sheetId") String sheetId, RollupService rollups, Out<Rollup> before) {
        before.set(rollups.snapshot(sheetId.trim()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.pool.PoolStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Merges the person into another on the sheet, refusing the same person or either of them retired: their claims,
 *  name and aliases, patrons, the patronage of them and their pool memberships move to the other; the rest of
 *  them is dropped. */
public class MergePerson {
    public void merge(@Val MergeRequest request, @Val Person person, PersonStore people, ClaimStore claims,
            PatronStore patrons, PoolStore pools, Out<MergedInto> merged) throws InvalidSheetException {
        Person into = request.into() == null ? null : people.find(person.getSheetId(), request.into());
        if (into == null) {
            throw new InvalidSheetException("No such person to merge into");
        }
        if (into.getId() == person.getId()) {
            throw new InvalidSheetException("A person cannot be merged into themselves");
        }
        if (person.isRetired() || into.isRetired()) {
            throw new InvalidSheetException("A retired person cannot be merged");
        }
        String sheetId = person.getSheetId();
        claims.moveAll(sheetId, person.getId(), into.getId());
        patrons.merge(sheetId, person.getId(), into.getId());
        pools.merge(sheetId, person.getId(), into.getId());
        people.mergeInto(person, into);
        merged.set(new MergedInto(people.find(sheetId, into.getId())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a merge: PERSON_MERGED sheet=<id> by=<user> from=<name> into=<name>, followed by how it moved the figures. */
public class AuditPersonMerged {
    public void audit(@Val MergeRequest request, @Val Person person, @Val MergedInto merged, @Val Rollup before,
            Audit audit, RollupService rollups) {
        audit.record("PERSON_MERGED sheet=" + person.getSheetId() + " by=" + request.user() + " from="
                + person.getName() + " into=" + merged.person().getName());
        rollups.record(person.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.hq.app.statement.StatementStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as they stand now. */
public class RespondWithMerged {
    public void respond(@Val MergedInto merged, StatementStore statements, PatronStore patrons, SheetStore sheets,
            ObjectResponse<PersonResponse> response) {
        Person person = merged.person();
        response.send(PersonResponse.from(person, sheets.today(person.getSheetId()),
                statements.summary(person.getSheetId(), person.getId()),
                patrons.of(person.getSheetId(), person.getId())));
    }
}
package net.officefloor.hq.app.person;

/** The person another was merged into (wrapped, so it is told apart from the person merged). */
public record MergedInto(Person person) {
}

