     *  sum of their figures as shown now, skipping n/a, as the screen shows a person's due-total for a
     *  period. A period's due-total is the sum of these. */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Lateness lateness = lateness(sheetId, today, all);
        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !countsAt(claim, atEnd.get(claim.getId()), person, today)
                        || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
                    continue;
                }
                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                }
            }
            totals.put(person.getId(), total);
        }
        return totals;
    }

    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        String who = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
                    + " overdue-total=" + after.overdueTotal());
        }
    }

    /** What the sheet's late charge follows on the date, for these claims (see {@link Lateness}). */
    private Lateness lateness(String sheetId, LocalDate today, List<Claim> all) {
        Map<Long, Person> byId = new HashMap<>();
        people.list(sheetId).forEach(person -> byId.put(person.getId(), person));
        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today,
                new Rounding(policyDate(sheetId), all), Lateness.graced(settings.graces(sheetId), byId::get));
    }

    /** The date the sheet's rounding turns on: the policy date set, else the sheet's today. */
    private LocalDate policyDate(String sheetId) {
        LocalDate policy = settings.policyDate(sheetId);
        return policy != null ? policy : sheets.today(sheetId);
    }

    /** Only OPEN, PENDING and SETTLED claims count, and an OPEN or PENDING claim dated within one of its
     *  person's holds, or of a person whose retirement date the sheet's today has reached, does not, unless a
     *  statement bound it; nor does an OPEN claim deferred on the sheet's today. */
    public static boolean counts(Claim claim, Person person, LocalDate today) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
                        && (claim.isStated() || !(person.heldOn(claim.getDate()) || person.retiredOn(today))));
    }

    /** Whether the claim counts by {@code status}, the status it had at a period's end (null when it
     *  was added after it): OPEN, PENDING or SETTLED then; and, as the live rules say, an OPEN claim
     *  deferred on the sheet's today does not, nor one open then and still open now dated within a hold
     *  of its person or of a person retired on the sheet's today, unless a statement bound it. */
    static boolean countsAt(Claim claim, ClaimStatus status, Person person, LocalDate today) {
        return status == ClaimStatus.SETTLED
                || (status != null && status.isOpen() && !claim.isDeferredOn(today)
                        && (claim.isStated() || !claim.getStatus().isOpen()
                                || !(person.heldOn(claim.getDate()) || person.retiredOn(today))));
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.DelegationStore;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** Lines that only report figures: never marked as made for a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    private final DelegationStore delegations;
    /** The records held back on this thread while a change that may yet be refused as a whole runs. */
    private final ThreadLocal<List<String>> held = new ThreadLocal<>();

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, DelegationStore delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user while a
     *  delegation of the steward role to them is in force ends with for=<the steward who delegated>. */
    public synchronized void record(String entry) {
        String delegator = delegator(entry);
        if (delegator != null) {
            entry = entry + " for=" + delegator;
        }
        List<String> holding = held.get();
        if (holding != null) {
            holding.add(entry);
            return;
        }
        append(entry);
    }

    /** Holds back the records this thread makes from now on, until {@link #release()} writes them or
     *  {@link #discard()} drops them: a change refused as a whole writes nothing. */
    public void hold() {
        held.set(new ArrayList<>());
    }

    /** Writes the records held back on this thread, in the order they were made, and stops holding. */
    public synchronized void release() {
        List<String> holding = held.get();
        held.remove();
        if (holding != null) {
            for (String entry : holding) {
                append(entry);
            }
        }
    }

    /** Drops the records held back on this thread, and stops holding. */
    public void discard() {
        held.remove();
    }

    private void append(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** The steward who delegated to the line's by= user, when the line is a change and a delegation is in force. */
    private String delegator(String entry) {
        String[] fields = entry.split(" ");
        if (FIGURES.contains(fields[0])) {
            return null;
        }
        String sheet = null;
        String by = null;
        for (String f : fields) {
            if (sheet == null && f.startsWith("sheet=")) {
                sheet = f.substring("sheet=".length());
            } else if (by == null && f.startsWith("by=")) {
                by = f.substring("by=".length());
            }
        }
        return sheet == null || by == null ? null : delegations.delegator(sheet, by);
    }

    /** The sheet's lines exactly as the file holds them, newest first; with a person's name, only the lines
     *  carrying name=<it> or person=<it>, compared as names are (case and surrounding spaces ignored). */
    public synchronized List<String> lines(String sheet, String person) {
        if (!Files.exists(file)) {
            return List.of();
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String marker = " sheet=" + sheet + " ";
        String name = person == null ? "" : person.trim().toLowerCase(java.util.Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (int i = all.size() - 1; i >= 0; i--) {
            String line = all.get(i);
            if ((line + " ").contains(marker) && (name.isEmpty() || about(line, name))) {
                found.add(line);
            }
        }
        return found;
    }

    /** Whether the line carries name=<name> or person=<name>: the value runs to the line's end or to the next field. */
    private static boolean about(String line, String name) {
        String lower = line.toLowerCase(java.util.Locale.ROOT);
        for (String key : List.of(" name=", " person=")) {
            int at = lower.indexOf(key);
            while (at >= 0) {
                int start = at + key.length();
                if (lower.startsWith(name, start)) {
                    String rest = lower.substring(start + name.length());
                    if (rest.isEmpty() || rest.matches(" [a-z][a-z0-9-]*=.*")) {
                        return true;
                    }
                }
                at = lower.indexOf(key, at + 1);
            }
        }
        return false;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

