package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The per-sheet settings. {@link #today(String)} is the date every date-dependent decision and
 * default in the app uses — never the real clock.
 */
@Repository
public class SheetStore {

    private final JdbcTemplate jdbc;

    public SheetStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today: as set on the sheet, else the real date. */
    public LocalDate today(String sheetId) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getObject(1, LocalDate.class), sheetId);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, today);
    }

    /** Records that the sheet has been loaded: from then on it exists. */
    public void markLoaded(String sheetId) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", sheetId);
    }

    /** Whether the sheet exists: it has been loaded (or changed). */
    public boolean exists(String sheetId) {
        Integer found = jdbc.queryForObject("SELECT (SELECT COUNT(*) FROM sheet_loaded WHERE id = ?)"
                + " + (SELECT COUNT(*) FROM sheet WHERE id = ?)", Integer.class, sheetId, sheetId);
        return found != null && found > 0;
    }

    /** Whether the sheet is archived: visible, but every change to it is refused. */
    public boolean archived(String sheetId) {
        List<Boolean> found = jdbc.query("SELECT archived FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBoolean(1), sheetId);
        return !found.isEmpty() && found.get(0);
    }

    /** Whether the sheet was archived while its today was on or before the date. */
    public boolean archivedBy(String sheetId, LocalDate date) {
        List<Boolean> found = jdbc.query("SELECT archived AND archived_on <= ? FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBoolean(1), date, sheetId);
        return !found.isEmpty() && found.get(0);
    }

    /** Archives the sheet, keeping its today as it reads now, and recording that today as the day it was archived. */
    public void archive(String sheetId) {
        LocalDate today = today(sheetId);
        jdbc.update("MERGE INTO sheet (id, today, archived, archived_on) KEY (id) VALUES (?, ?, TRUE, ?)", sheetId,
                today, today);
    }

    /** Refuses any change to an archived sheet. */
    public void refuseArchived(String sheetId) throws InvalidSheetException {
        if (archived(sheetId)) {
            throw new InvalidSheetException("The sheet is archived");
        }
    }
}
package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The roles assigned per sheet. A user name with none assigned is a clerk; one with a delegation of the
 *  steward role in force on the sheet's today acts as a steward (see {@link DelegationStore}). */
@Repository
public class RoleStore {

    private final JdbcTemplate jdbc;
    private final DelegationStore delegations;
    private final SheetStore sheets;

    public RoleStore(JdbcTemplate jdbc, DelegationStore delegations, SheetStore sheets) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.sheets = sheets;
    }

    /** Every role assigned on the sheet, by user name. */
    public List<RoleResponse> list(String sheetId) {
        return listFrom(sheetId, "sheet_role");
    }

    /** Every role assigned on the sheet at the end of the date (see {@link History}), by user name. */
    public List<RoleResponse> listAsOf(String sheetId, LocalDate date) {
        return listFrom(sheetId, History.asOf("sheet_role", "sheet_id, user_name", date));
    }

    private List<RoleResponse> listFrom(String sheetId, String table) {
        return jdbc.query("SELECT user_name, role FROM " + table + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).shown()),
                sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force, else
     *  the role assigned. */
    public Role find(String sheetId, String user) {
        return delegations.delegator(sheetId, user) != null ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's role as assigned on the sheet, delegations aside: clerk unless assigned otherwise. */
    public Role assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}
