import { currentAsOf } from '../session/session';

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request; `reason` is the text the server answered with (empty when none). */
export class HttpError extends Error {
  constructor(message: string, readonly reason: string, readonly status: number) {
    super(message);
  }
}

/** A change sent from a screen showing the sheet as of a date carries it, so the server refuses it. */
function withAsOf(init?: RequestInit): RequestInit | undefined {
  const asOf = currentAsOf();
  if (init?.method === undefined || asOf === '') return init;
  return { ...init, headers: { ...(init.headers as Record<string, string>), 'X-As-Of': asOf } };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, withAsOf(init));
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, reason, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useAsOf } from '../../session/session';

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default uses it, never the clock.
 *  An `archived` sheet stays visible but the server refuses every change to it. `asOf` (yyyy-MM-dd) is the
 *  date this screen shows the sheet as of, null when it shows it as it is now; `archived` is then as it
 *  stood at the end of that date. */
export type Sheet = { id: string; today: string; archived: boolean; asOf: string | null };

/** Every per-sheet query key starts with ['sheet', id], so loading a sheet re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

/** A per-sheet query key as read for the screen's as-of date: the key itself when there is none, so a
 *  change made (never while one is set) updates the very queries it read. */
export const asOfKey = <K extends readonly unknown[]>(key: K, asOf: string) =>
  (asOf === '' ? key : [...key, { asOf }]) as unknown as K;

/** A read path with the screen's as-of date added (as `asOf`), so the server answers as it stood then. */
export const asOfPath = (path: string, asOf: string) =>
  asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;

export function useSheet(id: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(sheetKey(id), asOf),
    queryFn: () => getJson<Sheet>(asOfPath(`/api/sheets/${encodeURIComponent(id)}`, asOf)),
    enabled: id !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while the sheet loads. Use it for every default date.
 *  While the screen shows the sheet as of a date, that date stands in for it in every figure. */
export function useSheetToday(id: string): string | undefined {
  const data = useSheet(id).data;
  return data?.asOf ?? data?.today;
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;

